// @file ./experiments/model-comparison.ts
import { defineExperiment } from "niceeval";
import { expressCodex } from "../agents/codex.ts";
import { codexSandbox } from "../sandbox.ts";

export default defineExperiment({
  description: "Compare a smaller Codex model on the same Express task",
  agent: expressCodex,
  model: "gpt-5.4-mini",
  runs: 1,
  maxConcurrency: 1,
  timeoutMs: 120_000,
  budget: 1,
  sandbox: codexSandbox(),
});
// @file ./experiments/baseline.ts
import { defineExperiment } from "niceeval";
import { expressCodex } from "../agents/codex.ts";
import { codexSandbox } from "../sandbox.ts";

export default defineExperiment({
  description: "Codex baseline on a focused Express regression task",
  agent: expressCodex,
  model: "gpt-5.4",
  runs: 1,
  maxConcurrency: 1,
  timeoutMs: 120_000,
  budget: 1,
  sandbox: codexSandbox(),
});
// @file ./niceeval.config.ts
import { defineConfig } from "niceeval";

export default defineConfig({
  // Add experiments/ with defineExperiment(...) to run evals.
  //
  // TODO(judge): semantic assertions (t.judge.*) are silently skipped until a judge
  // model is configured — an all-green run does not mean the judge ran. Any
  // OpenAI-compatible /chat/completions service works; the key is read from
  // OPENAI_API_KEY unless apiKeyEnv says otherwise.
  // judge: { model: "gpt-5.4-mini" },
});

// @file ./evals/res-send-status-418.eval.ts
import { defineEval } from "niceeval";
import { commandSucceeded, includes } from "niceeval/expect";

export default defineEval({
  description: "Add HTTP 418 regression coverage for res.sendStatus",
  async test(t) {
    await t.sandbox.uploadDirectory("..", ".", {
      ignore: ["node_modules", ".niceeval"],
    });
    await t.sandbox.runShell("ln -s /opt/express/node_modules node_modules");

    await t
      .send(
        "Add a regression test for Express's res.sendStatus() handling of HTTP 418 in " +
          "test/res.sendStatus.js. Follow the existing test style. The assertion must validate " +
          "the conventional reason phrase returned in the response body. Run only that test file " +
          "after making the change.",
      )
      .then((turn) => turn.succeeded());

    t.sandbox.fileChanged("test/res.sendStatus.js");

    const result = await t.sandbox.runCommand("node", [
      "/opt/express/node_modules/mocha/bin/mocha.js",
      "--require",
      "test/support/env",
      "--reporter",
      "spec",
      "--bail",
      "--check-leaks",
      "test/res.sendStatus.js",
    ]);
    t.check(result, commandSucceeded());

    const test = await t.sandbox.readFile("test/res.sendStatus.js");
    t.check(test, includes(/418/));
    t.check(test, includes(/I'm a Teapot/));
  },
});

