// ./sandbox.ts
import { dockerSandbox, e2bSandbox } from "niceeval/sandbox";

const localImage = "express-codex-evals:2026-08-19";
const e2bTemplate = "express-codex-evals:2026-08-19";

export function codexSandbox() {
  return process.env.CI
    ? e2bSandbox({ template: e2bTemplate })
    : dockerSandbox({ image: localImage });
}

// ./agents/codex.ts
import { codexAgent } from "niceeval/adapter";

// The built-in adapter maps Codex's JSONL transcript and file diff faithfully.
export const expressCodex = codexAgent();

// ./scripts/build-e2b-template.ts
import { Template } from "e2b";
import {
  e2bCodingAgentTemplate,
  verifyE2BNodeToolContract,
} from "niceeval/sandbox/e2b-template";

const template = verifyE2BNodeToolContract(
  e2bCodingAgentTemplate("codex")
    .copy(["package.json", "node_modules"], "/opt/express/", { user: "user" })
    .runCmd(
      "test -x \"$(command -v codex)\" && test -f /opt/express/node_modules/mocha/bin/mocha.js",
      { user: "user" },
    ),
);

await Template.build(template, "express-codex-evals:2026-08-19", {
  cpuCount: 2,
  memoryMB: 4096,
});

